#!/usr/bin/env python3
"""Synthetic FIT/squashfs image tests: never flash the generated bytes."""
import importlib.util
import struct
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location(
    "prebuilt_swap_probe", ROOT / "scripts/probe-prebuilt-kernel-swap.py")
probe = importlib.util.module_from_spec(spec)
assert spec.loader
spec.loader.exec_module(probe)


def fake_firmware(filename: Path, *, fit_size: int = 2048,
                  rootfs_offset: int = 65536) -> None:
    fit = bytearray(fit_size)
    fit[:4] = probe.FIT_MAGIC
    struct.pack_into(">I", fit, 4, fit_size)
    sqfs = bytearray(4096)
    sqfs[:4] = probe.SQUASHFS_MAGIC
    struct.pack_into("<HH", sqfs, 28, 4, 0)
    struct.pack_into("<Q", sqfs, 40, len(sqfs))
    with filename.open("wb") as output:
        output.write(fit)
        output.write(b"\0" * (rootfs_offset - fit_size))
        output.write(sqfs)
        output.write(b"\xff" * (1024 * 1024))


with tempfile.TemporaryDirectory() as rootdir:
    root = Path(rootdir)
    official = root / "official.bin"
    julius = root / "julius.bin"
    fake_firmware(official)
    fake_firmware(julius, fit_size=4096)
    extracted = root / "extracted"
    a = probe.inspect_sysupgrade(official, extracted=extracted, name="immortalwrt")
    b = probe.inspect_sysupgrade(julius, extracted=extracted, name="julius")
    result = probe.compare(a, b)
    assert result["same_layout"]
    assert result["julius_kernel_fits_target_partition"]
    assert not result["same_kernel_binary"]
    assert not result["kernel_abi_verified"]
    assert not result["publishable"]
    assert a["rootfs_offset"] == 65536
    assert a["rootfs_bytes"] == 4096
    assert (extracted / "julius.fit").read_bytes()[:4] == probe.FIT_MAGIC

    def rejects(change: bytes, expected: str) -> None:
        target = root / "corrupted.bin"
        target.write_bytes(change)
        try:
            probe.inspect_sysupgrade(target)
        except ValueError as e:
            assert expected in str(e), str(e)
        else:
            raise AssertionError("Accepted malformed sysupgrade: " + expected)

    orig = official.read_bytes()
    rejects(b"not a sysupgrade", "too small")
    rejects(b"\x00" * 10 + orig[10:], "expected an ARM64 FIT")
    tampered = bytearray(orig)
    struct.pack_into(">I", tampered, 4, probe.KERNEL_PARTITION_LIMIT + 1)
    rejects(tampered, "outside RE-SS-01")
    tampered = bytearray(orig)
    tampered[65536:65540] = b"BAD!"
    rejects(tampered, "exactly one")
    tampered = bytearray(orig)
    struct.pack_into("<Q", tampered, 65536 + 40, len(tampered) * 10)
    rejects(tampered, "invalid squashfs size")
print("PASS prebuilt RE-SS-01 FIT/squashfs boundary + safety gates")
